function formatMovieRuntime(minutes) {
  const n = Number(minutes);
  if (!Number.isFinite(n) || n <= 0) return "";
  const h = Math.floor(n / 60);
  const m = Math.round(n % 60);
  return h ? `${h} \u0433\u043E\u0434 ${m ? m + " \u0445\u0432" : ""}`.trim() : `${m} \u0445\u0432`;
}
